    private Control hit(float px, float py) {
        Control best = null;
        float bestD = Float.MAX_VALUE;
        for (Control c : all) {
            float slack = c.kind == K_STICK ? 1.5f : c.kind == K_DPAD ? 1.35f : 1.25f;
            boolean inside;
            if (c.rect != null) {
                RectF r = c.rect;
                float m = 0.25f * unit;
                inside = px >= r.left - m && px <= r.right + m && py >= r.top - m && py <= r.bottom + m;
            } else {
                inside = Math.hypot(px - c.cx, py - c.cy) <= c.r * slack;
            }
            if (inside && c.pointer < 0) {
                float dist = (float) Math.hypot(px - c.cx, py - c.cy) / Math.max(1f, c.r);
                if (dist < bestD) {
                    bestD = dist;
                    best = c;
                }
            }
        }
        return best;
    }

    private Control holding(int pointer) {
        for (Control c : all) {
            if (c.pointer == pointer) {
                return c;
            }
        }
        return null;
    }

    private void reset(Control c) {
        c.pointer = -1;
        c.pressed = false;
        c.sx = 0;
        c.sy = 0;
        c.dpad = 0;
    }

    private void track(Control c, float px, float py) {
        if (c.kind == K_STICK) {
            float dx = (px - c.cx) / c.r, dy = (py - c.cy) / c.r;
            float len = (float) Math.hypot(dx, dy);
            if (len > 1f) {
                dx /= len;
                dy /= len;
            }
            c.sx = dx;
            c.sy = dy;
            if (Math.hypot(px - c.downX, py - c.downY) > 0.25f * c.r) {
                c.moved = true;
            }
        } else if (c.kind == K_DPAD) {
            float dx = px - c.cx, dy = py - c.cy;
            int bits = 0;
            if (Math.hypot(dx, dy) > 0.22f * c.r) {
                double ang = Math.toDegrees(Math.atan2(-dy, dx));   // 0 = right, 90 = up
                if (ang < 0) {
                    ang += 360;
                }
                int sector = (int) Math.floor((ang + 22.5) / 45.0) % 8;
                int[] map = { DPAD_RIGHT, DPAD_RIGHT | DPAD_UP, DPAD_UP, DPAD_UP | DPAD_LEFT,
                              DPAD_LEFT, DPAD_LEFT | DPAD_DOWN, DPAD_DOWN, DPAD_DOWN | DPAD_RIGHT };
                bits = map[sector];
            }
            c.dpad = bits;
        } else {
            // A face-button finger may slide onto the neighbouring button.
            boolean isFace = false;
            for (Control f : face) {
                isFace |= f == c;
            }
            if (isFace) {
                Control best = null;
                float bestD = Float.MAX_VALUE;
                for (Control f : face) {
                    float dist = (float) Math.hypot(px - f.cx, py - f.cy);
                    if (dist <= f.r * 1.3f && dist < bestD && (f.pointer < 0 || f == c)) {
                        bestD = dist;
                        best = f;
                    }
                }
                if (best != null && best != c) {
                    int p = c.pointer;
                    reset(c);
                    best.pointer = p;
                    best.pressed = true;
                    performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);
                }
            }
        }
    }

    @Override
    public boolean onTouchEvent(MotionEvent ev) {
        if (!shown) {
            return false;
        }
        int action = ev.getActionMasked();
        int idx = ev.getActionIndex();
        boolean used = false;
        switch (action) {
        case MotionEvent.ACTION_DOWN:
        case MotionEvent.ACTION_POINTER_DOWN: {
            float px = ev.getX(idx), py = ev.getY(idx);
            Control c = hit(px, py);
            if (c != null) {
                c.pointer = ev.getPointerId(idx);
                c.pressed = true;
                c.downAt = ev.getEventTime();
                c.downX = px;
                c.downY = py;
                c.moved = false;
                if (c.kind == K_STICK) {
                    // The stick starts where the finger lands, not deflected.
                    c.downX = px;
                    c.downY = py;
                    c.sx = 0;
                    c.sy = 0;
                } else {
                    track(c, px, py);
                }
                performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);
                used = true;
            }
            break;
        }
        case MotionEvent.ACTION_MOVE:
            for (int i = 0; i < ev.getPointerCount(); i++) {
                Control c = holding(ev.getPointerId(i));
                if (c != null) {
                    track(c, ev.getX(i), ev.getY(i));
                    used = true;
                }
            }
            break;
        case MotionEvent.ACTION_UP:
        case MotionEvent.ACTION_POINTER_UP: {
            Control c = holding(ev.getPointerId(idx));
            if (c != null) {
                if (c.kind == K_STICK && !c.moved && ev.getEventTime() - c.downAt < 250) {
                    clickThumb(c);
                }
                reset(c);
                used = true;
            }
            break;
        }
        case MotionEvent.ACTION_CANCEL:
            for (Control c : all) {
                reset(c);
            }
            used = true;
            break;
        default:
            break;
        }
        if (used) {
            send();
            invalidate();
        }
        return used || action == MotionEvent.ACTION_MOVE || action == MotionEvent.ACTION_UP;
    }

    private final boolean[] thumbClick = new boolean[2];

    private void clickThumb(final Control c) {
        final int which = c == ls ? 0 : 1;
        thumbClick[which] = true;
        send();
        ui.postDelayed(() -> {
            thumbClick[which] = false;
            send();
        }, 120);
    }

    private static int axis(float v) {
        int i = Math.round(v * 32767f);
        return Math.max(-32767, Math.min(32767, i));
    }

    private void send() {
        int buttons = dpad.dpad;
        if (back.pressed) {
            buttons |= BACK;
        }
        if (start.pressed) {
            buttons |= START;
        }
        if (thumbClick[0]) {
            buttons |= LEFT_THUMB;
        }
        if (thumbClick[1]) {
            buttons |= RIGHT_THUMB;
        }
        state[0] = shown ? 1 : 0;
        state[1] = buttons;
        for (Control c : face) {
            state[2 + c.analog] = c.pressed ? 255 : 0;
        }
        state[2 + 6] = lt.pressed ? 255 : 0;
        state[2 + 7] = rt.pressed ? 255 : 0;
        state[10] = axis(ls.sx);
        state[11] = axis(-ls.sy);          // Xbox Y points up
        state[12] = axis(rs.sx);
        state[13] = axis(-rs.sy);
        if (Arrays.equals(state, sent) || !nativeOk) {
            return;
        }
        System.arraycopy(state, 0, sent, 0, state.length);
        int abxy = state[2] | (state[3] << 8) | (state[4] << 16) | (state[5] << 24);
        int bwlr = state[6] | (state[7] << 8) | (state[8] << 16) | (state[9] << 24);
        try {
            nativeTouchPad(state[0], state[1], abxy, bwlr, state[10], state[11], state[12],
                           state[13]);
        } catch (UnsatisfiedLinkError e) {
            nativeOk = false;              // libmain.so did not load: nothing to drive
            Log.w(TAG, "[TOUCH] no native side: " + e);
        }
    }
